{"t":"group","id":"sg","kind":"region","label":"Singapore (ap-southeast-1)","parent":null}
{"t":"node","id":"live","product":"live","label":"ApsaraVideo Live","group":"sg","why":"Ingests, transcodes and distributes live e-sports events."}
