{"t":"group","id":"vpc","kind":"vpc","label":"Platform VPC","parent":"sg"}
{"t":"node","id":"alb","product":"alb","label":"ALB","group":"vpc","zones":["a","b"],"why":"Routes API traffic across two zones."}
{"t":"node","id":"waf","product":"waf","label":"WAF","group":"vpc","attachTo":"alb","why":"Protects APIs from bots and injection attacks."}
{"t":"edge","id":"e-users-alb","from":"users","to":"alb","label":"API"}
{"t":"node","id":"app","product":"ecs","label":"App servers","group":"vpc","zones":["a","b"],"why":"Runs chat, profiles and stream metadata logic."}
