{"t":"node","id":"cache","product":"tair","label":"Session cache","group":"vpc","zones":["a","b"],"why":"Caches sessions and live chat presence."}
{"t":"node","id":"db","product":"rds","label":"Platform DB","group":"vpc","zones":["a","b"],"why":"Stores users, teams and match data."}
{"t":"edge","id":"e-app-cache","from":"app","to":"cache"}
{"t":"edge","id":"e-app-db","from":"app","to":"db","label":"SQL"}
{"t":"node","id":"media","product":"oss","label":"Media storage","group":"sg","why":"Holds raw video assets before VOD processing."}
{"t":"edge","id":"e-vod-media","from":"vod","to":"media","label":"assets"}
{"t":"node","id":"logs","product":"sls","label":"Logs","group":"sg","why":"Collects app and media logs for monitoring."}
{"t":"edge","id":"e-app-logs","from":"app","to":"logs","kind":"control"}
