{"t":"edge","id":"e-cloudsso-resdir","from":"cloudsso","to":"resdir","kind":"control"}
{"t":"node","id":"ram","product":"ram","label":"RAM","group":null,"why":"Roles and policies enforcing least privilege per account."}
{"t":"edge","id":"e-resdir-ram","from":"resdir","to":"ram","kind":"control"}
{"t":"node","id":"actiontrail","product":"actiontrail","label":"ActionTrail","group":null,"why":"Captures all console and API actions for audit compliance."}
{"t":"edge","id":"e-resdir-actiontrail","from":"resdir","to":"actiontrail","kind":"control"}
