{"t":"edge","id":"e-actiontrail-sls","from":"actiontrail","to":"sls","kind":"control"}
{"t":"node","id":"seccenter","product":"security-center","label":"Security Center","group":null,"why":"Agentic SOC for threat detection, SIEM and SOAR across accounts."}
{"t":"edge","id":"e-seccenter-sls","from":"seccenter","to":"sls","kind":"control"}
